-- PostgreSQL 18.6 clauses.c simplifies conditions before visiting dead results.
-- Direct type-input literals still belong to parse analysis, before planning.
CREATE SEQUENCE planner_checks;
CREATE TYPE planner_choice AS ENUM('a');
CREATE DOMAIN planner_checked AS planner_choice CHECK(nextval('planner_checks')>0);
CREATE FUNCTION planner_array() RETURNS planner_checked[] LANGUAGE sql AS 'SELECT ''{a}''::planner_checked[]';
CREATE FUNCTION planner_scalar() RETURNS integer LANGUAGE sql AS 'SELECT cardinality(''{a}''::planner_checked[])';
ALTER SEQUENCE planner_checks RESTART WITH 1;
BEGIN;
DECLARE planner_not NO SCROLL CURSOR FOR SELECT CASE WHEN NOT true THEN planner_array() ELSE NULL END;
DECLARE planner_comparison NO SCROLL CURSOR FOR SELECT CASE WHEN 1=2 THEN planner_array() ELSE NULL END;
DECLARE planner_simple_miss NO SCROLL CURSOR FOR SELECT CASE 1 WHEN 2 THEN planner_array() ELSE NULL END;
DECLARE planner_simple_hit NO SCROLL CURSOR FOR SELECT CASE 1 WHEN 1 THEN NULL ELSE planner_array() END;
DECLARE planner_and NO SCROLL CURSOR FOR SELECT false AND cardinality(planner_array())=1;
DECLARE planner_or NO SCROLL CURSOR FOR SELECT true OR cardinality(planner_array())=1;
DECLARE planner_coalesce NO SCROLL CURSOR FOR SELECT coalesce(1+1,planner_scalar());
SELECT 'dead_function_inputs',last_value,is_called FROM planner_checks;
FETCH ALL FROM planner_not;
FETCH ALL FROM planner_comparison;
FETCH ALL FROM planner_simple_miss;
FETCH ALL FROM planner_simple_hit;
FETCH ALL FROM planner_and;
FETCH ALL FROM planner_or;
FETCH ALL FROM planner_coalesce;
SELECT 'still_dead',last_value,is_called FROM planner_checks;
COMMIT;
SELECT CASE WHEN false THEN '{a}'::planner_checked[] ELSE NULL END;
SELECT 'parse_input',last_value,is_called FROM planner_checks;

ALTER SEQUENCE planner_checks RESTART WITH 1;
PREPARE planner_parameter(integer) AS SELECT CASE WHEN $1=0 THEN planner_scalar() ELSE 17 END;
EXECUTE planner_parameter(1);
SELECT 'unreached_parameter_branch',last_value,is_called FROM planner_checks;
EXECUTE planner_parameter(0);
SELECT 'reached_parameter_branch',last_value,is_called FROM planner_checks;
DEALLOCATE planner_parameter;
ALTER SEQUENCE planner_checks RESTART WITH 1;
PREPARE planner_text_parameter(text) AS SELECT CASE WHEN $1='go' THEN planner_scalar() ELSE 17 END;
EXECUTE planner_text_parameter('stop');
SELECT 'unreached_text_branch',last_value,is_called FROM planner_checks;
EXECUTE planner_text_parameter('go');
SELECT 'reached_text_branch',last_value,is_called FROM planner_checks;
DEALLOCATE planner_text_parameter;

-- Each rejected inline attempt checks its own body; execution then shares the
-- function's first runtime body across all following statement sites.
CREATE FUNCTION planner_text(integer) RETURNS text LANGUAGE sql AS
$$SELECT format('%s',$1) WHERE cardinality('{a}'::planner_checked[])=1$$;
CREATE CAST(integer AS text) WITH FUNCTION planner_text(integer) AS ASSIGNMENT;
CREATE TABLE planner_values(id integer PRIMARY KEY,value text);
ALTER SEQUENCE planner_checks RESTART WITH 1;
INSERT INTO planner_values VALUES(1,1),(2,2);
SELECT 'values',last_value FROM planner_checks;
INSERT INTO planner_values SELECT value,value FROM generate_series(3,5) source(value);
SELECT 'selected',last_value FROM planner_checks;
UPDATE planner_values SET value=id;
SELECT 'updated',last_value FROM planner_checks;
UPDATE planner_values target SET value=source.value FROM (VALUES(1,11),(2,12)) source(id,value) WHERE target.id=source.id;
SELECT 'joined_update',last_value FROM planner_checks;
INSERT INTO planner_values VALUES(1,'ignored'),(2,'ignored') ON CONFLICT(id) DO UPDATE SET value=excluded.id;
SELECT 'conflict_update',last_value FROM planner_checks;
MERGE INTO planner_values target USING (VALUES(1,21),(6,26)) source(id,value) ON target.id=source.id
WHEN MATCHED THEN UPDATE SET value=source.value
WHEN NOT MATCHED THEN INSERT(id,value) VALUES(source.id,source.value);
SELECT 'merged',last_value FROM planner_checks;
SELECT id,value FROM planner_values ORDER BY id;
DROP TABLE planner_values;
DROP CAST(integer AS text);
CREATE FUNCTION planner_projection(integer) RETURNS text LANGUAGE sql AS
$$SELECT format('%s',$1) || CASE WHEN cardinality('{a}'::planner_checked[])=1 THEN '' ELSE '' END$$;
CREATE CAST(integer AS text) WITH FUNCTION planner_projection(integer) AS ASSIGNMENT;
CREATE TABLE planner_projection_values(id integer PRIMARY KEY,value text);
ALTER SEQUENCE planner_checks RESTART WITH 1;
INSERT INTO planner_projection_values(value,id) SELECT value,id FROM (VALUES(11,1)) source(value,id);
SELECT 'reordered',last_value FROM planner_checks;
INSERT INTO planner_projection_values(value,id) SELECT * FROM (VALUES(22,2)) source(value,id);
SELECT 'wildcard',last_value FROM planner_checks;
INSERT INTO planner_projection_values(value,id) SELECT source.* FROM (VALUES(33,3)) source(value,id);
SELECT 'qualified_wildcard',last_value FROM planner_checks;
INSERT INTO planner_projection_values(value,id) SELECT (source).* FROM (VALUES(44,4)) source(value,id);
SELECT 'record_wildcard',last_value FROM planner_checks;
INSERT INTO planner_projection_values(value,id) SELECT 55,5 UNION ALL SELECT 66,6;
SELECT 'set_output',last_value FROM planner_checks;
SELECT id,value FROM planner_projection_values ORDER BY id;
DROP TABLE planner_projection_values;
DROP CAST(integer AS text);
-- Inlining substitutes normalized argument constants after parsing the body.
-- A direct checked literal still runs during that earlier parse step.
CREATE FUNCTION planner_outer(flag integer DEFAULT 1) RETURNS integer LANGUAGE sql AS
$$SELECT CASE WHEN flag=0 THEN planner_scalar() ELSE 17 END$$;
CREATE FUNCTION planner_pair(flag integer,unused integer) RETURNS integer LANGUAGE sql AS
$$SELECT CASE WHEN flag=0 THEN planner_scalar() ELSE 17 END$$;
CREATE FUNCTION planner_coalesce(value integer) RETURNS integer LANGUAGE sql AS
$$SELECT coalesce(value,planner_scalar())$$;
CREATE FUNCTION planner_negative(flag integer DEFAULT -1) RETURNS integer LANGUAGE sql AS
$$SELECT CASE WHEN flag<0 THEN 17 ELSE planner_scalar() END$$;
CREATE FUNCTION planner_variadic(VARIADIC items integer[]) RETURNS integer LANGUAGE sql AS
$$SELECT CASE WHEN $1[1] IS NULL THEN 17 ELSE planner_scalar() END$$;
CREATE FUNCTION planner_direct(flag integer) RETURNS integer LANGUAGE sql AS
$$SELECT CASE WHEN flag=0 THEN cardinality('{a}'::planner_checked[]) ELSE 17 END$$;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(1);
SELECT 'nested_literal',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer();
SELECT 'nested_default',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(flag=>1);
SELECT 'nested_named',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(1::smallint);
SELECT 'nested_coerced',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(NULL);
SELECT 'nested_known_null',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(0);
SELECT 'nested_reached',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(flag=>0);
SELECT 'nested_named_reached',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_pair(1,value) FROM (VALUES(NULL::integer),(0)) source(value);
SELECT 'nested_partly_known',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_outer(value) FROM (VALUES(1),(0)) source(value);
SELECT 'nested_unknown',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_coalesce(17);
SELECT 'nested_coalesce_known',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_coalesce(NULL);
SELECT 'nested_coalesce_null',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_negative();
SELECT 'nested_negative_default',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_variadic(1,2);
SELECT 'nested_variadic_expanded',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_variadic(VARIADIC ARRAY[]::integer[]);
SELECT 'nested_variadic_empty',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_variadic(VARIADIC ARRAY[NULL]::integer[]);
SELECT 'nested_variadic_null',last_value,is_called FROM planner_checks;
ALTER SEQUENCE planner_checks RESTART WITH 1;
SELECT planner_direct(1);
SELECT 'nested_direct_parse',last_value,is_called FROM planner_checks;
CREATE FUNCTION planner_varchar(integer,integer,boolean) RETURNS varchar LANGUAGE sql AS
$$SELECT (CASE WHEN $2=9 AND NOT $3 THEN format('%s',$1) ELSE format('%s',planner_scalar()) END)::varchar$$;
CREATE CAST(integer AS varchar) WITH FUNCTION planner_varchar(integer,integer,boolean) AS ASSIGNMENT;
CREATE TABLE planner_typmod_values(value varchar(5));
ALTER SEQUENCE planner_checks RESTART WITH 1;
INSERT INTO planner_typmod_values VALUES(11),(22);
SELECT value FROM planner_typmod_values ORDER BY value;
SELECT 'nested_typmod',last_value,is_called FROM planner_checks;
DROP TABLE planner_typmod_values;
DROP CAST(integer AS varchar);
DROP FUNCTION planner_varchar(integer,integer,boolean),planner_outer(integer),planner_pair(integer,integer),planner_coalesce(integer),planner_negative(integer),planner_variadic(integer[]),planner_direct(integer);
-- SQL CAST functions and operator procedures have the same inline-attempt
-- boundary as a written function call. Keep DECLARE and FETCH effects separate.
CREATE TABLE planner_operator_empty(value integer);
CREATE FUNCTION planner_cast(integer) RETURNS text LANGUAGE sql STRICT AS
$$SELECT format('%s',$1) WHERE cardinality('{a}'::planner_checked[])=1$$;
CREATE CAST(integer AS text) WITH FUNCTION planner_cast(integer);
CREATE FUNCTION planner_op_rejected(integer,integer) RETURNS integer LANGUAGE sql AS
$$SELECT $1+$2 WHERE cardinality('{a}'::planner_checked[])=1$$;
CREATE FUNCTION planner_op_accepted(integer,integer) RETURNS integer LANGUAGE sql AS
$$SELECT $1+$2+CASE WHEN cardinality('{a}'::planner_checked[])=1 THEN 0 ELSE 0 END$$;
CREATE FUNCTION planner_op_opaque(integer,integer) RETURNS integer LANGUAGE sql SET search_path=public AS
$$SELECT $1+$2 WHERE cardinality('{a}'::planner_checked[])=1$$;
CREATE FUNCTION planner_op_strict(integer,integer) RETURNS integer LANGUAGE sql STRICT AS
$$SELECT $1+$2 WHERE cardinality('{a}'::planner_checked[])=1$$;
CREATE FUNCTION planner_op_unary(integer) RETURNS integer LANGUAGE sql AS
$$SELECT $1 WHERE cardinality('{a}'::planner_checked[])=1$$;
CREATE OPERATOR #+ (LEFTARG=integer,RIGHTARG=integer,FUNCTION=planner_op_rejected);
CREATE OPERATOR #* (LEFTARG=integer,RIGHTARG=integer,FUNCTION=planner_op_accepted);
CREATE OPERATOR #/ (LEFTARG=integer,RIGHTARG=integer,FUNCTION=planner_op_opaque);
CREATE OPERATOR #? (LEFTARG=integer,RIGHTARG=integer,FUNCTION=planner_op_strict);
CREATE OPERATOR ~# (RIGHTARG=integer,FUNCTION=planner_op_unary);
