CREATE SEQUENCE singleton_effects START 10;
CREATE FUNCTION singleton_value(value bigint DEFAULT nextval('singleton_effects')) RETURNS bigint LANGUAGE sql VOLATILE AS 'SELECT $1';
BEGIN;
DECLARE singleton_cursor NO SCROLL CURSOR FOR SELECT singleton_value(),nextval('singleton_effects');
SELECT last_value,is_called FROM singleton_effects;
FETCH 0 FROM singleton_cursor;
SELECT last_value,is_called FROM singleton_effects;
FETCH 1 FROM singleton_cursor;
SELECT last_value FROM singleton_effects;
FETCH 1 FROM singleton_cursor;
SELECT last_value FROM singleton_effects;
CLOSE singleton_cursor;
COMMIT;
BEGIN;
DECLARE singleton_held NO SCROLL CURSOR WITH HOLD FOR SELECT singleton_value();
SELECT last_value FROM singleton_effects;
COMMIT;
FETCH ALL FROM singleton_held;
SELECT last_value FROM singleton_effects;
CLOSE singleton_held;
CREATE FUNCTION public.sum(value integer) RETURNS bigint LANGUAGE sql VOLATILE AS $$SELECT nextval('singleton_effects')+$1$$;
BEGIN;
DECLARE singleton_shadow NO SCROLL CURSOR FOR SELECT public.sum(7);
SELECT last_value FROM singleton_effects;
FETCH 1 FROM singleton_shadow;
SELECT last_value FROM singleton_effects;
CLOSE singleton_shadow;
COMMIT;
DROP FUNCTION public.sum(integer);
DROP FUNCTION singleton_value(bigint);
DROP SEQUENCE singleton_effects;
