SELECT * LIMIT 0;
SELECT *,1/0 LIMIT 0;
SELECT true+1,*;
SELECT *,true+1;
SELECT missing.*;
SELECT missing.* LIMIT 0;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT *;
ROLLBACK;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT * LIMIT 0;
ROLLBACK;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT *,1/0 LIMIT 0;
ROLLBACK;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT true+1,*;
ROLLBACK;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT *,true+1;
ROLLBACK;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT missing.*;
ROLLBACK;
BEGIN;
DECLARE invalid_singleton CURSOR FOR SELECT missing.* LIMIT 0;
ROLLBACK;
CREATE TABLE zero_column_cursor_source();
INSERT INTO zero_column_cursor_source DEFAULT VALUES;
BEGIN;
DECLARE valid_empty_columns CURSOR FOR SELECT * FROM zero_column_cursor_source;
FETCH NEXT FROM valid_empty_columns;
CLOSE valid_empty_columns;
DECLARE valid_empty_columns CURSOR FOR SELECT source.* FROM zero_column_cursor_source source;
FETCH NEXT FROM valid_empty_columns;
CLOSE valid_empty_columns;
COMMIT;
DROP TABLE zero_column_cursor_source;
BEGIN;
DECLARE singleton_mode CURSOR FOR SELECT 7 AS value;
SELECT is_scrollable FROM pg_cursors WHERE name='singleton_mode';
FETCH NEXT FROM singleton_mode;
CLOSE singleton_mode;
DECLARE singleton_mode SCROLL CURSOR FOR SELECT 7 AS value;
SELECT is_scrollable FROM pg_cursors WHERE name='singleton_mode';
FETCH NEXT FROM singleton_mode;
CLOSE singleton_mode;
COMMIT;
